import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.D1JEzK2q.js";const k=JSON.parse('{"title":"CLI and HTTP API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli-api.md","filePath":"reference/cli-api.md"}'),n={name:"reference/cli-api.md"};function d(o,e,r,h,l,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="cli-and-http-api" tabindex="-1">CLI and HTTP API <a class="header-anchor" href="#cli-and-http-api" aria-label="Permalink to &quot;CLI and HTTP API&quot;">​</a></h1><p>The CLI is a client for a running gateway, with local commands for lifecycle and diagnostics. Start with help to inspect exact options:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude-gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><h2 id="connect-to-the-right-gateway" tabindex="-1">Connect to the right gateway <a class="header-anchor" href="#connect-to-the-right-gateway" aria-label="Permalink to &quot;Connect to the right gateway&quot;">​</a></h2><p><code>--url</code> and <code>--key</code> explicitly select the server and API key. Environment alternatives are <code>CLAUDE_GATEWAY_URL</code> and <code>CLAUDE_GATEWAY_API_KEY</code>; a local CLI can read the admin key from configuration automatically. When a local gateway is detected, ordinary commands prefer its local address over <code>gateway.publicUrl</code>.</p><p><code>--json</code> reserves stdout for the JSON result. <code>--data</code> merges a JSON object into a write request. See <a href="https://github.com/0xMaxMa/claude-gateway/blob/main/CLI.md" target="_blank" rel="noreferrer">CLI.md</a> for the generated command inventory, exact precedence, and exit codes.</p><h2 id="make-a-read-only-api-request" tabindex="-1">Make a read-only API request <a class="header-anchor" href="#make-a-read-only-api-request" aria-label="Permalink to &quot;Make a read-only API request&quot;">​</a></h2><p>Using an API key already stored in your shell environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:10850/api/v1/agents</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Api-Key: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CLAUDE_GATEWAY_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>The result lists agents accessible to that key. The API also accepts <code>Authorization: Bearer &lt;key&gt;</code>. <code>/health</code> is public and returns liveness only. Dashboard and host monitoring need admin access when keys are configured.</p><h2 id="send-a-message" tabindex="-1">Send a message <a class="header-anchor" href="#send-a-message" aria-label="Permalink to &quot;Send a message&quot;">​</a></h2><p>Replace <code>assistant</code> with an accessible agent ID. <code>chat_id</code> identifies this integration&#39;s conversation namespace:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:10850/api/v1/agents/assistant/messages</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Api-Key: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CLAUDE_GATEWAY_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;message&quot;:&quot;Introduce yourself in one sentence.&quot;,&quot;chat_id&quot;:&quot;example-app&quot;}&#39;</span></span></code></pre></div><p>Save the returned session identifier if you need to continue that session; send it as <code>session_id</code> with the same <code>chat_id</code>. An unknown session ID returns <code>404</code>, rather than silently creating a different session. Add <code>&quot;stream&quot;: true</code> and use <code>curl -N</code> for SSE; consume error events as well as text and completion events. When <code>orchestration_enabled</code> is true, an acknowledgement can precede task completion. Continue observing <a href="/claude-gateway/api/orchestration.html#session-activity">session activity</a> and history for the eventual result.</p><h2 id="find-the-right-surface" tabindex="-1">Find the right surface <a class="header-anchor" href="#find-the-right-surface" aria-label="Permalink to &quot;Find the right surface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Endpoint family</th></tr></thead><tbody><tr><td>Agents and messages</td><td><code>/api/v1/agents</code></td></tr><tr><td>Available models</td><td><code>/api/v1/models</code></td></tr><tr><td>Session operations</td><td><code>/api/v1/agents/:agentId/sessions</code></td></tr><tr><td>Cron jobs</td><td><code>/api/v1/crons</code></td></tr><tr><td>App installation jobs</td><td><code>/api/v1/apps</code></td></tr><tr><td>Generated route metadata</td><td><code>/api/v1/_meta/routes</code></td></tr></tbody></table><p>The gateway mounts router-local <code>/v1/...</code> paths under <code>/api</code>, so public URLs use <code>/api/v1/...</code>. Root endpoints such as <code>/health</code> and <code>/dashboard</code> retain their own paths. Use the <a href="/claude-gateway/api/">HTTP API reference</a> for complete schemas, SSE events, error codes and authorization rules, including <a href="/claude-gateway/api/tasks.html">tasks</a>, <a href="/claude-gateway/api/voice.html">voice</a>, <a href="/claude-gateway/api/apps.html">apps</a> and <a href="/claude-gateway/api/connectors.html">connectors</a>.</p>`,17)])])}const g=a(n,[["render",d]]);export{k as __pageData,g as default};
